package com.studentassignment.api;
import com.studentassignment.model.UserRole;import com.studentassignment.security.UserContext;import com.studentassignment.service.*;import java.util.*;import org.springframework.core.io.Resource;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/submissions") public class SubmissionController {
 private final SubmissionService service;private final UserContext context;private final FileStorageService files;public SubmissionController(SubmissionService service,UserContext context,FileStorageService files){this.service=service;this.context=context;this.files=files;}
 @GetMapping("/my") @PreAuthorize("hasRole('STUDENT')") public Map<String,Object> mine(Authentication auth){return Map.of("data",service.mine(context.id(auth)).stream().map(Views::submission).toList());}
 @GetMapping("/dashboard") @PreAuthorize("hasRole('STUDENT')") public Map<String,Object> dashboard(Authentication auth){var d=service.dashboard(context.id(auth));return Map.of("data",Map.of("totalSubmissions",d.totalSubmissions(),"pendingReview",d.pendingReview(),"graded",d.graded(),"late",d.late()));}
 @GetMapping("/assignment/{assignmentId}") @PreAuthorize("hasRole('FACULTY')") public Map<String,Object> assignment(@PathVariable Long assignmentId,Authentication auth){return Map.of("data",service.forAssignment(assignmentId,context.id(auth)).stream().map(Views::submission).toList());}
 @PostMapping(value="/upload",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @PreAuthorize("hasRole('STUDENT')") public Map<String,Object> upload(@RequestParam Long assignmentId,@RequestPart MultipartFile file,Authentication auth){return Map.of("data",Views.submission(service.upload(assignmentId,file,context.id(auth))));}
 @PutMapping("/grade/{id}") @PreAuthorize("hasRole('FACULTY')") public Map<String,Object> grade(@PathVariable Long id,@RequestBody AuthDtos.GradeRequest request,Authentication auth){if(request.marks()==null)throw new ApiException(HttpStatus.BAD_REQUEST,"Marks are required.");return Map.of("data",Views.submission(service.grade(id,request.marks(),request.feedback(),context.id(auth))));}
 @GetMapping("/{id}/download") public ResponseEntity<Resource> download(@PathVariable Long id,Authentication auth){Long userId=context.id(auth);UserRole role=auth.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_FACULTY"))?UserRole.FACULTY:UserRole.STUDENT;if(!service.mayRead(id,userId,role))throw ApiException.forbidden();var s=service.get(id);return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(s.getFileName()).build().toString()).body(files.load(s.getFilePath()));}
}
